WITH with_windows AS (SELECT *, ROUND(discount_pct / SUM(discount_pct) OVER (PARTITION BY promo_code), 4) AS discount_pct_share, AVG(discount_pct) OVER (ORDER BY starts_on, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS discount_pct_avg_5, LEAD(discount_pct, 1) OVER (PARTITION BY channel, promo_code ORDER BY discount_pct, id) AS next_discount_pct FROM promotions) SELECT promo_code, CASE WHEN discount_pct >= 0.36 THEN 'LARGE' ELSE 'SMALL' END AS discount_pct_tier, COUNT(DISTINCT channel) AS distinct_channels, COUNT(*) FILTER (WHERE channel = 'partner') AS partner_rows, COUNT(CASE WHEN promo_code = 'WELCOME5' THEN 1 END) AS welcome5_count, SIZE(COLLECT_SET(channel)) AS num_channels, SUM(CASE WHEN channel = 'mobile' THEN discount_pct_avg_5 ELSE 0 END) AS mobile_discount_pct_avg_5 FROM with_windows GROUP BY promo_code, CASE WHEN discount_pct >= 0.36 THEN 'LARGE' ELSE 'SMALL' END
